<script setup lang="ts">
import BillingPanel from '../../components/BillingPanel.vue'
import { ref,computed,nextTick } from 'vue'
import { onLoad,onShow } from '@dcloudio/uni-app'
import { request,upload,idempotencyKey,statuses,date,priorities } from '../../api'
import { useSession } from '../../stores/session'
const session=useSession(),id=ref(''),order=ref<any>(null),logs=ref<any[]>([]),records=ref<any[]>([]),photos=ref<any[]>([]),busy=ref(false),reasonType=ref(''),reason=ref(''),content=ref(''),resultImages=ref<{path:string,id:string}[]>([]),uploading=ref(false),evaluation=ref<any>(null),score=ref(5),evaluationText=ref(''),complaint=ref(''),showComplaint=ref(false),error=ref(false),attempts=new Map<string,string>()
const isOwner=computed(()=>session.activeRole==='RESIDENT'&&order.value?.residentId===session.user?.id)
const isWorker=computed(()=>session.activeRole==='WORKER'&&order.value?.workerId===session.user?.workerId)
async function load(){if(!id.value)return;error.value=false;try{order.value=await request(`/repair/orders/${id.value}`);logs.value=await request(`/repair/orders/${id.value}/logs`);records.value=await request(`/repair/orders/${id.value}/work-records`);evaluation.value=await request(`/repair/orders/${id.value}/evaluations`);const media=await request(`/repair/orders/${id.value}/media`);photos.value=await Promise.all(media.map(async(m:any)=>({...m,...await request(`/files/${m.fileId}/access-url`)})));if(focusBilling.value){await nextTick();uni.pageScrollTo({selector:'#billing-panel',duration:200});focusBilling.value=false}}catch{error.value=true}}
const focusBilling=ref(false)
onLoad(options=>{focusBilling.value=options?.billing==='1';if(!session.requireLogin())return;id.value=String(options?.id||'');load()});onShow(()=>{if(id.value)load()})
function requestKey(action:string,body:any){const hash=action+JSON.stringify(body);if(!attempts.has(hash))attempts.set(hash,idempotencyKey());return attempts.get(hash)!}
async function action(name:string,extra:any={}){busy.value=true;const body={version:order.value.version,...extra};try{await request(`/repair/orders/${id.value}/${name}`,'POST',body,requestKey(name,body));uni.showToast({title:'工单已更新',icon:'success'});reasonType.value='';reason.value='';content.value='';resultImages.value=[];await load()}catch(e){if((e as any).status===409)await load()}finally{busy.value=false}}
async function confirm(){const result=await new Promise<UniApp.ShowModalRes>(resolve=>uni.showModal({title:'确认维修完成？',content:'确认后工单将关闭，你可以继续评价维修服务。',success:resolve}));if(result.confirm)await action('confirm')}
async function reasonSubmit(){if(!reason.value.trim()){uni.showToast({title:'请填写原因',icon:'none'});return}await action(reasonType.value,{reason:reason.value})}
async function choose(){const result=await new Promise<UniApp.ChooseImageSuccessCallbackResult>((resolve,reject)=>uni.chooseImage({count:9-resultImages.value.length,sizeType:['compressed'],success:resolve,fail:reject}));uploading.value=true;try{for(const path of result.tempFilePaths)resultImages.value.push({path,id:await upload(path)})}finally{uploading.value=false}}
async function finish(){if(!content.value.trim()){uni.showToast({title:'请填写维修结果',icon:'none'});return}await action('finish',{content:content.value,attachmentIds:resultImages.value.map(i=>i.id)})}
async function evaluate(){busy.value=true;const body={score:score.value,content:evaluationText.value};try{evaluation.value=await request(`/repair/orders/${id.value}/evaluations`,'POST',body,requestKey('evaluate',body));uni.showToast({title:'感谢你的评价',icon:'success'})}finally{busy.value=false}}
async function complain(){if(!complaint.value.trim()){uni.showToast({title:'请描述投诉原因',icon:'none'});return}busy.value=true;const body={content:complaint.value};try{await request(`/repair/orders/${id.value}/complaints`,'POST',body,requestKey('complain',body));showComplaint.value=false;complaint.value='';uni.showToast({title:'投诉已提交',icon:'success'})}finally{busy.value=false}}
async function progress(){if(!content.value.trim())return;busy.value=true;try{await request(`/repair/orders/${id.value}/work-records`,'POST',{content:content.value});content.value='';await load()}finally{busy.value=false}}
</script>
<template><button class="secondary" @click="uni.navigateTo({url:`/pages/support/index?orderId=${id}`})">咨询这张工单</button><view class="page"><view v-if="error" class="error" @click="load">工单加载失败，点击重新加载</view><template v-if="order"><view class="row"><text class="eyebrow">第 {{order.roundNo}} 轮维修</text><text class="pill">{{statuses[order.status]}}</text></view><view class="page-title">{{order.title}}</view><view class="small">{{order.orderNo}}</view><view class="card spaced"><view class="muted">{{order.communityName}} · {{order.facilityScope==='PUBLIC'?order.locationText:`${order.buildingNo}栋 ${order.unitNo}单元 ${order.roomNo}室`}}</view><view class="divider"></view><view class="body-text">{{order.description}}</view><view class="photo-grid"><image v-for="photo in photos" :key="photo.id" :src="photo.url" mode="aspectFill" @click="uni.previewImage({urls:photos.map(p=>p.url),current:photo.url})"/></view><view class="divider"></view><view class="row"><text class="muted">{{order.categoryName}} · {{priorities[order.priority]}}</text><text class="muted">{{order.workerName||'待分配维修人员'}}</text></view><view v-if="order.appointmentStartAt" class="notice">期望上门：{{date(order.appointmentStartAt)}} ～ {{date(order.appointmentEndAt)}}</view></view>
<BillingPanel :order="order" :owner="isOwner"/><template v-if="isOwner"><button v-if="['SUBMITTED','PENDING_DISPATCH'].includes(order.status)" class="secondary" @click="reasonType='cancel'">取消报修</button><template v-if="order.status==='PENDING_CONFIRM'"><button class="primary" :loading="busy" @click="confirm">确认维修完成</button><button class="secondary" @click="reasonType='rework'">问题还未解决，申请返修</button></template><view v-if="order.status==='CLOSED'" class="card"><view class="section-title">服务评价</view><view v-if="evaluation" class="notice">已评价：{{evaluation.score}}分<br>{{evaluation.content}}</view><template v-else><view class="tab-row"><text v-for="value in [1,2,3,4,5]" :key="value" :class="{active:score===value}" @click="score=value">{{value}}分</text></view><textarea v-model="evaluationText" class="field textarea" maxlength="500" placeholder="说说这次维修服务的体验（选填）"/><button class="primary" :loading="busy" @click="evaluate">提交评价</button></template></view><button v-if="['IN_PROGRESS','PENDING_CONFIRM','CLOSED'].includes(order.status)" class="secondary" @click="showComplaint=!showComplaint">反馈服务问题</button></template>
<template v-if="isWorker"><template v-if="order.status==='ASSIGNED'"><button class="primary" :loading="busy" @click="action('accept')">接受任务</button><button class="secondary" @click="reasonType='reject'">拒绝任务</button></template><button v-if="order.status==='ACCEPTED'" class="primary" :loading="busy" @click="action('start')">开始维修</button><view v-if="order.status==='IN_PROGRESS'" class="card"><view class="section-title">维修处理</view><textarea v-model="content" class="field textarea" maxlength="2000" placeholder="填写维修过程或处理结果"/><view class="photo-grid"><image v-for="(image,index) in resultImages" :key="image.id" :src="image.path" mode="aspectFill" @click="resultImages.splice(index,1)"/></view><button class="secondary" :loading="uploading" :disabled="uploading||resultImages.length>=9" @click="choose">添加维修结果图片</button><button class="secondary" :disabled="busy" @click="progress">保存过程记录</button><button class="primary" :loading="busy" :disabled="busy||uploading" @click="finish">提交维修结果，等待验收</button></view></template>
<view v-if="reasonType" class="card spaced"><view class="label">{{reasonType==='cancel'?'取消原因':reasonType==='reject'?'拒单原因':'返修原因'}}</view><textarea v-model="reason" class="field textarea" maxlength="500" placeholder="请填写原因"/><button class="primary" :loading="busy" @click="reasonSubmit">确认提交</button><button class="secondary" @click="reasonType=''">暂不操作</button></view><view v-if="showComplaint" class="card spaced"><view class="label">服务问题</view><textarea v-model="complaint" class="field textarea" maxlength="1000" placeholder="描述问题，物业会跟进处理"/><button class="primary" :loading="busy" @click="complain">提交投诉</button></view>
<view class="section-title">维修记录</view><view v-if="!records.length" class="muted">维修处理后，记录将显示在这里。</view><view v-for="record in records" :key="record.id" class="card"><view class="row"><text class="pill">第{{record.roundNo}}轮</text><text class="small">{{date(record.createdAt)}}</text></view><view class="body-text spaced">{{record.content}}</view></view><view class="section-title">工单时间线</view><view v-for="log in [...logs].reverse()" :key="log.id" class="timeline-entry"><view class="row"><text>{{statuses[log.newStatus]}}</text><text class="small">{{date(log.createdAt)}}</text></view><view v-if="log.remark" class="muted">{{log.remark}}</view></view></template></view></template>
<style scoped>.timeline-entry{padding:24rpx 0 24rpx 28rpx;margin-left:8rpx;border-left:3rpx solid #cce3da;position:relative}.timeline-entry:before{content:'';position:absolute;left:-8rpx;top:34rpx;background:#0b7774;width:12rpx;height:12rpx;border-radius:50%}.timeline-entry .row>text:first-child{font-size:26rpx;font-weight:500}</style>
